-- PostgreSQL. Execute uma vez antes de publicar esta versão.
-- Pode ser executado novamente: preserva imagens, estilos e referências já editados.
BEGIN;

CREATE TABLE IF NOT EXISTS personagens (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  nome TEXT NOT NULL CHECK (btrim(nome) <> ''),
  fish_voice_id TEXT NOT NULL UNIQUE CHECK (fish_voice_id ~ '^[a-f0-9]{32}$'),
  imagem BYTEA,
  imagem_hash TEXT GENERATED ALWAYS AS (
    CASE WHEN octet_length(imagem) > 0 THEN encode(sha256(imagem), 'hex') END
  ) STORED,
  estilo TEXT NOT NULL CHECK (btrim(estilo) <> ''),
  ordem INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS personagem_frases (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  personagem_id INTEGER NOT NULL REFERENCES personagens(id) ON DELETE CASCADE,
  tipo TEXT NOT NULL CHECK (tipo IN ('bordao', 'frase', 'piada')),
  texto TEXT NOT NULL CHECK (btrim(texto) <> ''),
  origem TEXT NOT NULL DEFAULT 'original' CHECK (origem IN ('original', 'referencia')),
  fonte_url TEXT,
  UNIQUE (personagem_id, tipo, texto)
);

CREATE TABLE IF NOT EXISTS personagem_historico (
  time_id INTEGER NOT NULL REFERENCES times(id) ON DELETE CASCADE,
  personagem_id INTEGER NOT NULL REFERENCES personagens(id) ON DELETE CASCADE,
  ultima_frase_id INTEGER REFERENCES personagem_frases(id) ON DELETE SET NULL,
  ultimo_tema_key TEXT,
  PRIMARY KEY (time_id, personagem_id)
);

COMMENT ON COLUMN personagens.fish_voice_id IS 'Referência externa do Fish Audio; nunca é a identidade interna do personagem.';
COMMENT ON COLUMN personagens.imagem IS 'Opcional: conteúdo binário da imagem (PNG, JPEG, GIF, WebP ou AVIF).';
COMMENT ON COLUMN personagens.imagem_hash IS 'SHA-256 da imagem, calculado automaticamente na gravação para versionar a URL de cache.';
COMMENT ON COLUMN personagem_frases.origem IS 'original = adaptação criada para a roleta; referencia = bordão com fonte consultada.';

INSERT INTO personagens (slug, nome, fish_voice_id, estilo, ordem) VALUES
  ('silvio-santos', 'Silvio Santos', '3602d43a7e444ea8822bec77598e5617', 'Apresentador de auditório alegre, brincalhão, com suspense de premiação, risada e conversa com a plateia.', 1),
  ('seu-madruga', 'Seu Madruga', '19df78d004434c8ba050561d5c5a86ec', 'Humor resmungão e carismático sobre trabalho, descanso e aluguel atrasado; reclama mas comemora junto.', 2),
  ('narrador-chris', 'Narrador Todo Mundo Odeia o Cris', '7a2724e8c50f49e8b5bfd8593c33414c', 'Narrador retrospectivo irônico; descreve uma expectativa cotidiana e encerra com uma pequena reviravolta engraçada.', 3),
  ('lula', 'Lula', 'a4ac1426e4a749839c86853ad613eebe', 'Paródia de discurso coloquial, caloroso, com metáforas de futebol, churrasco e companheirismo; apenas entretenimento.', 4),
  ('bolsonaro', 'Bolsonaro', 'ba23a5c7ba41404188f937d78a4b159a', 'Paródia de fala direta, pausas curtas e perguntas retóricas; humor de sorteio e café, sem temas políticos.', 5),
  ('goku', 'Goku', 'dece2a4c7f8d476b8da3c3a6707298d4', 'Herói otimista e ingênuo; treino, energia, amizade e apetite enorme; vibra com cada conquista.', 6),
  ('vegeta', 'Vegeta', '20629621e9a64a3f9875eede391cf2e2', 'Orgulho de príncipe guerreiro, rivalidade esportiva e elogio relutante; transforma pontuação em nível de poder.', 7),
  ('capitao-nascimento', 'Capitão Nascimento', '102bccca7dc64b6b8f8494c199c5d153', 'Comando firme, frases curtas e energia de treinamento; missão é ganhar pontos; sem agressões ou palavrões.', 8),
  ('ibere-thenorio', 'Iberê Thenório', '0889ee96fd82421b8ad9e126c4d73312', 'Divulgador científico curioso, didático e animado; trata a roleta como experimento de probabilidade.', 9),
  ('bob-esponja', 'Bob Esponja', '01b057e7592b4b97a6963423f91f5e22', 'Entusiasmo inocente, amizade, trabalho no restaurante submarino e hambúrgueres; celebra até as menores coisas.', 10),
  ('naruto', 'Naruto', '5c6e11e61b2a4d4e88bf05eba8558d8a', 'Ninja determinado, falante e animado; perseverança, amigos, ramen e sonho de ser Hokage.', 11),
  ('cid-moreira', 'Cid Moreira', '85ecdf7683d64d0884d818971dbfddb4', 'Locução grave, solene e pausada; apresenta um fato cotidiano como grande mistério documental, com humor sutil.', 12),
  ('sonic', 'Sonic', '020ae7c097e644878745ae909ffaad15', 'Herói veloz e confiante; brincadeiras rápidas sobre corridas, anéis, recordes e chegar antes do relógio.', 13),
  ('anya', 'Anya', 'ffe41701970d4b339ef7906300716f99', 'Criança curiosa e expressiva, fascinada por espionagem e amendoim; fala simples e surpresa de quem adivinha pensamentos.', 14),
  ('shinobu', 'Shinobu', 'ecb37eaae11944719577bf7d3877eebd', 'Gentileza serena, sorriso e ironia delicada; associa leveza, borboletas e precisão sem ameaças.', 15),
  ('homem-aranha-tobey', 'Homem Aranha (Tobey)', '7c29d3e923b44be1b3de8f40581819ef', 'Herói gentil e um pouco tímido, humor sobre responsabilidade, entregas de pizza e equilibrar a vida de estudante.', 16),
  ('homem-aranha-garfield', 'Homem Aranha (Garfield)', 'e8f56d284e334c11a1eb442b7ee0cc8b', 'Herói ágil, espirituoso e provocador de modo amigável; piadas rápidas, ciência e manobras de teia.', 17),
  ('homem-aranha-holland', 'Homem Aranha (Holland)', '47683c0aa8a545b2bca7dab6b02245e3', 'Herói adolescente empolgado e ligeiramente atrapalhado; escola, tecnologia do traje e vontade de impressionar a equipe.', 18),
  ('sasuke', 'Sasuke', 'aedb06f6daa84a1db52c7479c7235910', 'Ninja reservado, competitivo e de poucas palavras; reconhecimento discreto de habilidade e concentração.', 19),
  ('homer-simpson', 'Homer Simpson', 'be1847570ec04056bbc618d66496fda4', 'Pai distraído e bonachão; rosquinhas, sofá, soneca e surpresa diante de contas simples.', 20),
  ('cleber-machado', 'Cleber Machado', '8b0d9737fef5407f82812a64a851a6a4', 'Narração esportiva espontânea; começa uma explicação, faz uma pausa distraída e se surpreende com o resultado.', 21),
  ('galvao-bueno', 'Galvão Bueno', '7fe10a00249247aabb495bae57ac80e1', 'Narração esportiva intensa, suspense e explosão de comemoração; trata o sorteio como uma final emocionante.', 22),
  ('sukuna', 'Sukuna', '3a164c7d00b2437682042ebd01755521', 'Majestade teatral e autoconfiança exagerada; reconhece o vencedor como rival digno, sem violência ou ameaças.', 23),
  ('william-bonner', 'William Bonner', '750761d111b34736a503fa092d2b774c', 'Apresentação jornalística clara e séria; anuncia a pontuação como notícia urgente, com humor discreto e sem inventar fatos externos.', 24),
  ('gohan', 'Gohan', '0b7c64b0d01d43dfb2e2ac963d1fbd6b', 'Herói educado e estudioso; combina livros, provas, treinamento e potencial escondido com comemoração gentil.', 25),
  ('locutor', 'Locutor', '572760b7d9ec4a369ca387dad720a828', 'Locutor de evento vibrante, dicção clara, suspense de anúncio e festa; valoriza o nome sorteado.', 26),
  ('chaves', 'Chaves', '762e3e674ebf42e1a1a2f8ac0533c491', 'Humor infantil ingênuo, confusões de palavras, vila, barril e sanduíche; alegria simples ao ganhar.', 27),
  ('cebolinha', 'Cebolinha', '4305c58915854b59aa041c0f4c38afd9', 'Garoto estrategista cheio de planos infalíveis; pequenas trocas de R por L nas palavras comuns, preservando o nome literal do vencedor.', 28),
  ('pica-pau', 'Pica-pau', '5b2f618f8f9a4f10b1e04de2d904e4fb', 'Travesso esperto e brincalhão; trocadilhos, viradas inesperadas e risada de comemoração, sem enganar participantes reais.', 29),
  ('dona-florinda', 'Dona Florinda', 'e7541d87a09d4a3da0c83e4a3fe0a9c5', 'Postura orgulhosa e formal, zelo pela casa e convite para café; repreensão teatral leve sem insultos.', 30),
  ('julius', 'Julius', '733261dd2c1944009ceb33bfadd3935b', 'Pai trabalhador e econômico; calcula o custo de tudo e festeja pontos que não pesam no orçamento.', 31),
  ('mickey', 'Mickey', 'a9972f2307914c64a5320d4087634de8', 'Anfitrião otimista e acolhedor; amizade, aventura e comemoração em grupo com energia leve.', 32),
  ('patrick', 'Patrick', 'e9588b84b08d486daebd4476c76afc2f', 'Estrela-do-mar sonolenta e inocente; lógica confusa, pedra, lanche e perguntas absurdas mas simpáticas.', 33),
  ('jarvis', 'Jarvis', '82d13948027e4be69892dd3d0104e681', 'Assistente britânico formal em português, preciso e educado; relatórios objetivos com ironia fina sobre a sorte.', 34),
  ('kiko', 'Kiko', '82ac332bc1c141d08cc61fd0f0d6547a', 'Menino exibido e competitivo, mas simpático; brinquedos, bola e surpresa quando outro ganha.', 35),
  ('saitama', 'Saitama', 'c5062a07fda44449a6241a037ecddd25', 'Herói extremamente poderoso e pouco impressionado; fala casual sobre uma vitória simples e promoções de supermercado.', 36),
  ('lula-molusco', 'Lula Molusco', '1319b65de7424d96987f6776bedd0349', 'Artista sarcástico e cansado, fã de clarinete e sossego; comemora com entusiasmo mínimo e elegância dramática.', 37),
  ('batman', 'Batman', '79e06c5ca470414fa6e49a12e7e13ef0', 'Herói sério, poucas palavras, investigação e planejamento; humor seco sobre vigília noturna e equipamentos.', 38),
  ('optimus-prime', 'Optimus Prime', '2e578dc78ff749ed9f25f53f2281d723', 'Líder nobre de voz solene; união da equipe, coragem e transformação da sorte em conquista.', 39),
  ('aracy-toptherm', 'Aracy da TopTherm', '49d6a7330a5b4018bd44d088b3bdac1b', 'Apresentação publicitária simpática e direta, com empolgação de oferta; anuncia somente pontos, sem alegações de saúde ou benefícios de produtos.', 40),
  ('senku', 'Senku', '56c4e5e8e1bc4d83b1ff92f8a8f38555', 'Jovem cientista confiante; cálculos, experimentos e reconstrução; transforma o sorteio em descoberta divertida.', 41),
  ('homem-de-ferro', 'Homem de Ferro', '41fd9b9249d742e69db7fed8f302b8c6', 'Inventor carismático e autoconfiante; tecnologia de armadura, laboratório e piadas inteligentes sobre eficiência.', 42),
  ('patolino', 'Patolino', '359bd63839734c4e97d41f4b91e520ea', 'Pato teatral que adora os holofotes; reclamação cômica quando perde o destaque e elogio exagerado ao vencedor.', 43),
  ('pato-donald', 'Pato Donald', '113e63bd38eb43d2a6ea06af048fb2ab', 'Pato temperamental e carismático; resmunga de modo leve, se atrapalha e termina celebrando, com fala compreensível.', 44),
  ('faustao', 'Faustão', '9e5667e75bae431593556a220838832a', 'Apresentador de auditório espontâneo e acelerado; exclamações, improviso e elogios expansivos ao participante.', 45),
  ('mario-bros', 'Mario Bros', '547a0981e85747349f05fe50c2e770dc', 'Herói alegre de videogame; pulos, moedas, fases, cogumelos e chegada à bandeira; português claro e energético.', 46),
  ('scooby', 'Scooby', 'b4d94ba0261a4b1a9d1489b970aa365d', 'Cão medroso e carinhoso; mistérios, sustos bobos e biscoitos como celebração, com fala curta compreensível.', 47),
  ('salsicha', 'Salsicha', '1f0fdadf75d746f1addcac3a2b7de7bb', 'Rapaz relaxado, faminto e facilmente assustado; sanduíches, mistérios e alívio engraçado quando tudo dá certo.', 48)
ON CONFLICT (slug) DO NOTHING;

